const body = $json.body ?? $json;

// Auto detect channel if not explicitly provided
let source = body.channel ?? $json.channel;

if (!source) {
  if (body.object === 'page' || body.entry?.[0]?.messaging) {
    source = 'facebook_messenger';
  } else if (body.data?.senderData || body.instanceId) {
    source = 'whatsapp';
  } else if (body.message?.chat) {
    source = 'telegram';
  } else {
    source = 'unknown';
  }
}

let userId = '';
let message = '';
let customerName = '';
let customerPhone = '';
let customerEmail = '';
let conversationId = '';

if (source === 'facebook_messenger') {
  const event = body.entry?.[0]?.messaging?.[0] ?? body;
  userId = String(event.sender?.id ?? body.user_id ?? '');
  message = String(event.message?.text ?? body.message ?? body.text ?? '');
  customerName = String(body.customer_name ?? '');
  conversationId = String(event.sender?.id ?? body.conversation_id ?? '');
} else if (source === 'whatsapp') {
  const data = body.data ?? body;
  userId = String(data.senderData?.chatId ?? data.senderData?.sender ?? body.user_id ?? '');
  message = String(data.messageData?.textMessageData?.textMessage ?? data.message ?? body.text ?? '');
  customerName = String(data.senderData?.senderName ?? body.customer_name ?? '');
  customerPhone = String(data.senderData?.sender ?? body.phone ?? '');
  conversationId = userId;
} else if (source === 'telegram') {
  const tg = body.message ?? body;
  userId = String(tg.from?.id ?? body.user_id ?? '');
  message = String(tg.text ?? body.text ?? body.message ?? '');
  customerName = String(tg.from?.first_name ?? body.customer_name ?? '');
  conversationId = String(tg.chat?.id ?? body.conversation_id ?? userId);
}

return {
  json: {
    channel: source,
    user_id: userId,
    conversation_id: conversationId,
    message: message,
    customer_name: customerName,
    customer_phone: customerPhone,
    customer_email: customerEmail,
    received_at: new Date().toISOString()
  }
};

// 1. Merge All Resort Data theke shob item read kora
const itemsData = $input.all().map(item => item.json);

let channel = 'unknown';
let user_id = '';
let conversation_id = '';
let message = '';
let customer_name = '';

// 1. Telegram Check
try {
  const telegramData = $('Telegram Trigger').first()?.json;
  if (telegramData?.message?.text) {
    channel = 'telegram';
    user_id = String(telegramData.message.from?.id || '');
    conversation_id = String(telegramData.message.chat?.id || '');
    message = telegramData.message.text || '';
    customer_name = telegramData.message.from?.first_name || 'Telegram User';
  }
} catch (e) {}

// 2. WhatsApp (GREENAPI Trigger) Check
try {
  const waData = $('GREENAPI Trigger').first()?.json;
  if (waData) {
    const body = waData.body || waData;
    const textMsg = body.messageData?.textMessageData?.textMessage || body.messageData?.extendedTextMessageData?.text || '';
    if (textMsg) {
      channel = 'whatsapp';
      user_id = String(body.senderData?.chatId || body.chatData?.chatId || '');
      conversation_id = user_id;
      message = textMsg;
      customer_name = body.senderData?.senderName || 'WhatsApp User';
    }
  }
} catch (e) {}

// 3. Facebook Messenger (Webhook) Check
try {
  const fbData = $('Webhook').first()?.json;
  if (fbData) {
    const entry = fbData.body?.entry?.[0] || fbData.entry?.[0];
    const messaging = entry?.messaging?.[0];
    if (messaging?.message?.text) {
      channel = 'facebook';
      user_id = String(messaging.sender?.id || '');
      conversation_id = user_id;
      message = messaging.message.text || '';
      customer_name = 'Facebook User';
    }
  }
} catch (e) {}

// AI Agent-er jonno Output pathano
return [{
  json: {
    channel,
    user_id,
    conversation_id,
    message,
    customer_name,
    resort_data: JSON.stringify(itemsData, null, 2)
  }
}];

// 1. AI Output Parse
let result = {};
try {
  const rawOutput = $json.output || $input.first()?.json?.output || '{}';
  result = typeof rawOutput === 'string' ? JSON.parse(rawOutput) : rawOutput;
} catch (e) {
  result = {};
}

const detectedChannel = $('Build Resort AI Context').first()?.json?.channel || 'facebook';
const reply = result.customer_reply || result.reply_text || "ধন্যবাদ! আমরা আপনার অনুরোধটি রিসিভ করেছি।";

// 2. Auto Generate Receipt ID
const randomNum = Math.floor(10000 + Math.random() * 90000);
const receiptId = "REC-" + randomNum;

// 3. Smart Extraction for Nested AI Data
const extData = result.extracted_data || result.details || {};
const innerDetails = extData.details || extData || {};

// Extract Food Items
let itemsList = innerDetails.items_ordered || extData.items_ordered || result.items_ordered || result.items;
const items = Array.isArray(itemsList) 
  ? itemsList.join(', ') 
  : (itemsList || 'N/A');

// Extract Price
const amount = innerDetails.total_price || extData.total_price || result.total_price || result.amount || 'N/A';

// Extract Customer Info
const customerName = extData.customer_name || innerDetails.customer_name || result.customer_name || 'N/A';
const customerPhone = extData.customer_phone || innerDetails.customer_phone || result.customer_phone || 'N/A';
const customerEmail = extData.customer_email || innerDetails.customer_email || result.customer_email || 'N/A';
const orderDate = innerDetails.date_time || innerDetails.check_in_date || extData.date_time || extData.check_in_date || new Date().toLocaleString();

// 4. Output with Dual Mapping (for Sheets & Telegram)
return [{
  json: {
    // Sheet Keys
    "Receipt ID": receiptId,
    "Customer Phone": customerPhone,
    "Customer Email": customerEmail,
    "Customer Name": customerName,
    "Items": items,
    "Amount": amount,
    "Date": orderDate,
    "Timestamp": new Date().toLocaleString(),
    "source_channel": detectedChannel,

    // Telegram Standard Keys (N/A এরর ঠেকানোর জন্য)
    "receipt_id": receiptId,
    "customer_name": customerName,
    "customer_phone": customerPhone,
    "customer_email": customerEmail,
    "items": items,
    "amount": amount,
    "order_date": orderDate,

    // Internal Variables
    "intent": result.intent || "order",
    "customer_reply": reply,
    "message": reply,
    "details": extData
  }
}];

// 1. Input data read
const data = $json;

// 2. Extract Fields safely
const receiptId = data["Receipt ID"] || data.receipt_id || 'N/A';
const name = data["Customer Name"] || data.customer_name || data.extracted_data?.customer_name || 'N/A';
const phone = data["Customer Phone"] || data.customer_phone || data.extracted_data?.customer_phone || 'N/A';
const email = data["Customer Email"] || data.customer_email || data.extracted_data?.customer_email || 'N/A';
const items = data["Items"] || data.items || 'N/A';
const amount = data["Amount"] || data.amount || 'N/A';
const dateStr = data["Date"] || data.order_date || 'N/A';
const channel = data["source_channel"] || data.source_channel || 'facebook';
const intent = data.intent || 'order';

// 3. Construct Clean Telegram Notification Text
let text = "";

if (intent === 'booking') {
  text = `🚨 NEW BOOKING ALERT - MOLLYWOOD RESORT 🚨\n\n` +
         `🧾 Receipt ID: ${receiptId}\n` +
         `👤 Customer Name: ${name}\n` +
         `📞 Phone: ${phone}\n` +
         `✉️ Email: ${email}\n` +
         `🏠 Cottage/Room: ${items}\n` +
         `📅 Dates: ${dateStr}\n` +
         `📱 Channel: ${channel}\n\n` +
         `Please check Google Sheets for details!`;
} else {
  text = `🚨 NEW ORDER ALERT - MOLLYWOOD RESORT 🚨\n\n` +
         `🧾 Receipt ID: ${receiptId}\n` +
         `👤 Customer Name: ${name}\n` +
         `📞 Phone: ${phone}\n` +
         `✉️ Email: ${email}\n\n` +
         `🍲 Items: ${items}\n` +
         `💰 Total Amount: ৳${amount}\n` +
         `📅 Serving Date & Time: ${dateStr}\n` +
         `📱 Channel: ${channel}\n\n` +
         `Please process the order immediately!`;
}

// 4. Return Object (Matching 'Run Once for Each Item' mode)
return {
  message: text,
  chat_id: data.chat_id || ""
};

const parseNode = $('Parse AI JSON')?.first()?.json || {};
const contextNode = $('Build Resort AI Context')?.first()?.json || {};

const channel = (parseNode.source_channel || parseNode.channel || contextNode.channel || 'whatsapp').toLowerCase();

let chatId = parseNode.user_id || parseNode.chat_id || contextNode.user_id || contextNode.conversation_id || '';

// If WhatsApp, ensure strictly standard phone@c.us format
if (channel === 'whatsapp' && chatId) {
  const cleanNum = chatId.replace(/[^0-9]/g, '');
  chatId = `${cleanNum}@c.us`;
}

const replyMsg = parseNode.customer_reply || parseNode.reply_text || parseNode.output || parseNode.text || 'Hello! Welcome to Mollywood Resort.';

return [{
  json: {
    channel: channel,
    user_id: String(chatId),
    conversation_id: String(chatId),
    reply_text: replyMsg
  }
}];
